namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and rhetoric." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and their impact on civilization." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published extensively on CS education.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming).", Credits = 4, Schedule = "TTh 10:30–11:50 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and has industry experience at major tech companies.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "310", Title = "Database Systems", Description = "Design and implementation of relational databases, SQL, normalization, and transaction processing.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez researches distributed database systems and has contributed to several open-source database projects." },
            new() { Id = 4, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "450", Title = "Machine Learning", Description = "Introduction to machine learning algorithms including regression, classification, clustering, and neural networks.", Credits = 4, Schedule = "TTh 2:00–3:20 PM", InstructorName = "Dr. Alan Wright", InstructorBio = "Dr. Wright leads the university's AI research lab and has published over 40 papers in top ML conferences.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator known for making calculus accessible to all students." },
            new() { Id = 6, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "TTh 9:00–10:20 AM", InstructorName = "Dr. Emily Torres", InstructorBio = "Dr. Torres specializes in applied linear algebra and numerical methods.", IsFeatured = true },
            new() { Id = 7, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator known for making calculus accessible to all students." },
            new() { Id = 8, DepartmentId = 3, DepartmentCode = "ENG", CourseNumber = "101", Title = "College Writing", Description = "Develop critical reading and writing skills through analysis of diverse texts and composition of academic essays.", Credits = 3, Schedule = "MWF 10:00–10:50 AM", InstructorName = "Prof. Diana Reed", InstructorBio = "Prof. Reed is a published author and has taught writing at the university level for over 20 years." },
            new() { Id = 9, DepartmentId = 3, DepartmentCode = "ENG", CourseNumber = "250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present day.", Credits = 3, Schedule = "TTh 1:00–2:20 PM", InstructorName = "Dr. Michael Brown", InstructorBio = "Dr. Brown is an expert in 20th-century American fiction and has published three books on the subject." },
            new() { Id = 10, DepartmentId = 4, DepartmentCode = "PHYS", CourseNumber = "101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.", Credits = 4, Schedule = "MWF 2:00–2:50 PM + Lab Thu 3:00–5:00 PM", InstructorName = "Dr. Lisa Nguyen", InstructorBio = "Dr. Nguyen is an experimental physicist whose research focuses on condensed matter physics.", IsFeatured = true },
            new() { Id = 11, DepartmentId = 4, DepartmentCode = "PHYS", CourseNumber = "201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Includes weekly laboratory sessions.", Credits = 4, Schedule = "MWF 3:00–3:50 PM + Lab Tue 3:00–5:00 PM", InstructorName = "Dr. Lisa Nguyen", InstructorBio = "Dr. Nguyen is an experimental physicist whose research focuses on condensed matter physics." },
            new() { Id = 12, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "101", Title = "World Civilizations", Description = "Survey of major world civilizations from antiquity to the early modern period.", Credits = 3, Schedule = "TTh 11:00 AM–12:20 PM", InstructorName = "Dr. Patricia Hayes", InstructorBio = "Dr. Hayes is a specialist in ancient Mediterranean cultures and archaeological methodology." },
            new() { Id = 13, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "220", Title = "Modern European History", Description = "Europe from the French Revolution to the present, covering political, social, and cultural transformations.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant has published widely on 19th-century European political movements." },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.DepartmentCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollment(EnrollmentRequest request) => _enrollments.Add(request);
}

