@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted!</h4>
        <p>Your enrollment request has been received. You will be notified once it has been processed.</p>
    </div>
    <a href="courses" class="btn btn-primary">Browse More Courses</a>
}
else
{
    <p>Fill out the form below to request enrollment in a course.</p>

    <form method="post" class="col-md-8" @formname="enrollment">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" class="form-control" id="studentName" name="Model.StudentName"
                   value="@Model.StudentName" required />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                   value="@Model.StudentId" required placeholder="e.g., STU-12345" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select class="form-select" id="courseId" name="Model.CourseId" required>
                <option value="">-- Select a Course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                        @course.DepartmentCode @course.CourseNumber – @course.Title
                    </option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-success">Submit Request</button>
        <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
    </form>
}

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> courses = new();
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }

        if (HttpMethods.IsPost(httpContext.Request.Method) && Model.CourseId > 0 && !string.IsNullOrWhiteSpace(Model.StudentName))
        {
            Catalog.SubmitEnrollment(Model);
            submitted = true;
        }
    }

    [CascadingParameter] public HttpContext httpContext { get; set; } = default!;
}
